function validate([arr]) {
  if (!Array.isArray(arr) || arr.length !== 4) return 'arr holds exactly 4 digits.';
  if (arr.some(v => !Number.isInteger(v) || v < 0 || v > 9)) return 'Each value is a digit from 0 to 9.';
  return null;
}

