function largestTimeFromDigits(arr) {
  let best = -1;

  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      for (let k = 0; k < 4; k++) {
        if (i === j || i === k || j === k) {
          continue;
        }
        const l = 6 - i - j - k;
        const hours = 10 * arr[i] + arr[j];
        const minutes = 10 * arr[k] + arr[l];
        if (hours < 24 && minutes < 60) {
          best = Math.max(best, hours * 60 + minutes);
        }
      }
    }
  }
  if (best === -1) {
    return "";
  }
  const hh = String(Math.floor(best / 60)).padStart(2, "0");
  const mm = String(best % 60).padStart(2, "0");
  return hh + ":" + mm;
}

