function largestTimeFromDigits(arr) {
  // Walk the clock backwards from 23:59 and stop at the first reading whose digits match arr.
  const want = [...arr].sort().join('');
  for (let total = 23 * 60 + 59; total >= 0; total--) {
    const text = String(Math.floor(total / 60)).padStart(2, '0') + String(total % 60).padStart(2, '0');
    if (text.split('').sort().join('') === want) return text.slice(0, 2) + ':' + text.slice(2);
  }
  return '';
}

