function generate(rand, size) {
  // Small digits make valid times common; occasionally allow any digit so that some inputs have no answer.
  const top = size === 'large' || rand() < 0.4 ? 10 : 6;
  return [Array.from({ length: 4 }, () => Math.floor(rand() * top))];
}
